/* SepoaSealManagementManager.doSelectSSHNE */ SELECT DISTINCT SHNE.HOUSE_CODE ,SHNE.COMPANY_CODE ,SHNE.MANAGE_NUMBER ,SHNE.DOC_NO ,SHNE.STATUS ,SHNE.ADD_DATE ,SHNE.ADD_TIME ,SHNE.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHNE.HOUSE_CODE AND USMT.USER_ID = SHNE.ADD_USER_ID) AS ADD_USER_NAME_LOC ,SHNE.CHANGE_DATE ,SHNE.CHANGE_TIME ,SHNE.CHANGE_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHNE.HOUSE_CODE AND USMT.USER_ID = SHNE.CHANGE_USER_ID) AS CHANGE_USER_NAME_LOC ,SHNE.DEL_FLAG ,SHNE.SUBJECT ,SHNE.SEAL_TYPE ,SHNE.SEAL_MG_DEPT ,SHNE.SEAL_MG_USER_ID ,SHNE.SUB_MG_DEPT ,SHNE.SUB_MG_USER_ID ,SHNE.SEAL_USE ,SHNE.CAL_BASIS_131 ,SHNE.CAL_BASIS_132 ,SHNE.RECV_TYPE ,SHNE.SEAL_DATE ,SHNE.SEAL_ATTACH_NO ,SHNE.CONFIRM_DATE ,SHNE.SEND_DATE ,SHNE.SEND_USER_ID ,SHNE.RECV_USER_ID ,SHNE.RECV_DATE ,SHNE.RECV_ADDR ,SHNE.SEAL_USE_DEPT ,SHNE.ELECTRON_FLAG ,SHNE.REAL_FLAG ,SHNE.EXTERNAL_FLAG ,SHNE.REASON ,SHNE.CAL_REMARK ,SHNE.SEAL_CATEGORY ,SHNE.PUBLIC_YN ,#DB_OWNER#GETDEPTNAME(SHNE.HOUSE_CODE, SHNE.COMPANY_CODE, SHNE.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHNE.HOUSE_CODE, SHNE.COMPANY_CODE, SHNE.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME ,#DB_OWNER#GETDEPTNAME(SHNE.HOUSE_CODE, SHNE.COMPANY_CODE, SHNE.SUB_MG_DEPT, ${session.LANGUAGE}) AS SUB_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHNE.HOUSE_CODE, SHNE.COMPANY_CODE, SHNE.SUB_MG_USER_ID, ${session.LANGUAGE}) AS SUB_MG_USER_NAME ,'NE' AS APPLY_TYPE , (SELECT SEAL_ID FROM SSEAL WHERE SSEAL.HOUSE_CODE = SHNE.HOUSE_CODE AND SSEAL.COMPANY_CODE = SHNE.COMPANY_CODE AND SSEAL.MANAGE_NUMBER = SHNE.MANAGE_NUMBER) AS SEAL_ID FROM SDCAM DCAM INNER JOIN SSHNE SHNE ON DCAM.HOUSE_CODE = SHNE.HOUSE_CODE AND DCAM.COMPANY_CODE = SHNE.COMPANY_CODE AND DCAM.CODE = SHNE.MANAGE_NUMBER AND DCAM.SEQ = SHNE.DOC_NO LEFT OUTER JOIN SUSMT USMT ON USMT.HOUSE_CODE = SHNE.HOUSE_CODE AND USMT.USER_ID = SHNE.SEAL_MG_USER_ID WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = $S{COMPANY_CODE} AND DCAM.USER_COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND SHNE.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND SHNE.DOC_NO = $S{DOC_NO} AND #DB_OWNER#NVL(SHNE.DEL_FLAG, 'N') = 'N' AND SHNE.STATUS IN( $INS{STATUS}) AND SHNE.STATUS = $S{F_STATUS} AND SHNE.ADD_DATE >= $S{F_CALENDAR_FROM} AND SHNE.ADD_DATE <= $S{F_CALENDAR_TO} AND ( 1=1 AND UPPER(SHNE.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHNE.DOC_NO) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHNE.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND 'NE' IN ($INS{F_APPLY_TYPE})

/* SepoaSealManagementManager.doSelectSSHRE */ SELECT DISTINCT SHRE.HOUSE_CODE ,SHRE.COMPANY_CODE ,SHRE.MANAGE_NUMBER ,SHRE.DOC_NO ,SHRE.STATUS ,SHRE.ADD_DATE ,SHRE.ADD_TIME ,SHRE.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHRE.HOUSE_CODE AND USMT.USER_ID = SHRE.ADD_USER_ID) AS ADD_USER_NAME_LOC ,SHRE.CHANGE_DATE ,SHRE.CHANGE_TIME ,SHRE.CHANGE_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHRE.HOUSE_CODE AND USMT.USER_ID = SHRE.CHANGE_USER_ID) AS CHANGE_USER_NAME_LOC ,SHRE.DEL_FLAG ,SHRE.REASON ,SHRE.RETURN_REMARK ,'RE' AS APPLY_TYPE ,SEAL.MANAGE_NUMBER ,SEAL.SUBJECT ,SEAL.SEAL_TYPE ,SEAL.SEAL_DATE ,SEAL.SEAL_MG_USER_ID ,SEAL.SEAL_MG_DEPT ,SEAL.SEAL_CATEGORY ,SEAL.PUBLIC_YN ,#DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME FROM SDCAM DCAM INNER JOIN SSHRE SHRE ON DCAM.HOUSE_CODE = SHRE.HOUSE_CODE AND DCAM.COMPANY_CODE = SHRE.COMPANY_CODE AND DCAM.CODE = SHRE.MANAGE_NUMBER AND DCAM.SEQ = SHRE.DOC_NO INNER JOIN SSEAL SEAL ON SHRE.HOUSE_CODE = SEAL.HOUSE_CODE AND SHRE.COMPANY_CODE = SEAL.COMPANY_CODE AND SHRE.MANAGE_NUMBER = SEAL.MANAGE_NUMBER LEFT OUTER JOIN SUSMT USMT ON USMT.HOUSE_CODE = SEAL.HOUSE_CODE AND USMT.USER_ID = SEAL.SEAL_MG_USER_ID WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = $S{COMPANY_CODE} AND DCAM.USER_COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND SHRE.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND SHRE.DOC_NO = $S{DOC_NO} AND SHRE.STATUS IN( $INS{STATUS}) AND SHRE.STATUS = $S{F_STATUS} AND SHRE.ADD_DATE >= $S{F_CALENDAR_FROM} AND SHRE.ADD_DATE <= $S{F_CALENDAR_TO} AND #DB_OWNER#NVL(SHRE.DEL_FLAG, 'N') = 'N' AND ( 1=1 AND UPPER(SHRE.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHRE.DOC_NO) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SEAL.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND 'RE' IN ($INS{F_APPLY_TYPE})

/* SepoaSealManagementManager.doSelectSSHLO */ SELECT DISTINCT SHLO.HOUSE_CODE ,SHLO.COMPANY_CODE ,SHLO.MANAGE_NUMBER ,SHLO.DOC_NO ,SHLO.STATUS ,SHLO.ADD_DATE ,SHLO.ADD_TIME ,SHLO.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHLO.HOUSE_CODE AND USMT.USER_ID = SHLO.ADD_USER_ID) AS ADD_USER_NAME_LOC ,SHLO.CHANGE_DATE ,SHLO.CHANGE_TIME ,SHLO.CHANGE_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHLO.HOUSE_CODE AND USMT.USER_ID = SHLO.CHANGE_USER_ID) AS CHANGE_USER_NAME_LOC ,SHLO.DEL_FLAG ,SHLO.LOSS_DEPT ,SHLO.LOSS_USER_ID ,SHLO.LOSS_DT_PLACE ,SHLO.LOSS_REMARK ,SHLO.REASON ,SHLO.ATTACH_NO ,'LO' AS APPLY_TYPE ,#DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SHLO.LOSS_DEPT, ${session.LANGUAGE}) AS LOSS_USER_NAME ,#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SHLO.LOSS_USER_ID, ${session.LANGUAGE}) AS LOSS_DEPT_NAME ,SEAL.MANAGE_NUMBER ,SEAL.SUBJECT ,SEAL.SEAL_TYPE ,SEAL.SEAL_DATE ,SEAL.SEAL_MG_USER_ID ,SEAL.SEAL_MG_DEPT ,SEAL.SEAL_CATEGORY ,SEAL.PUBLIC_YN ,#DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME FROM SDCAM DCAM INNER JOIN SSHLO SHLO ON DCAM.HOUSE_CODE = SHLO.HOUSE_CODE AND DCAM.COMPANY_CODE = SHLO.COMPANY_CODE AND DCAM.CODE = SHLO.MANAGE_NUMBER AND DCAM.SEQ = SHLO.DOC_NO INNER JOIN SSEAL SEAL ON SHLO.HOUSE_CODE = SEAL.HOUSE_CODE AND SHLO.COMPANY_CODE = SEAL.COMPANY_CODE AND SHLO.MANAGE_NUMBER = SEAL.MANAGE_NUMBER LEFT OUTER JOIN SUSMT USMT ON USMT.HOUSE_CODE = USMT.HOUSE_CODE AND USMT.USER_ID = SEAL.SEAL_MG_USER_ID WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = $S{COMPANY_CODE} AND DCAM.USER_COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND SHLO.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND SHLO.DOC_NO = $S{DOC_NO} AND SHLO.STATUS IN( $INS{STATUS}) AND SHLO.STATUS = $S{F_STATUS} AND SHLO.ADD_DATE >= $S{F_CALENDAR_FROM} AND SHLO.ADD_DATE <= $S{F_CALENDAR_TO} AND #DB_OWNER#NVL(SHLO.DEL_FLAG, 'N') = 'N' AND ( 1=1 AND UPPER(SHLO.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHLO.DOC_NO) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SEAL.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND 'LO' IN ($INS{F_APPLY_TYPE})

/* SepoaSealManagementManager.doSelectSSHUP */ SELECT DISTINCT SHUP.HOUSE_CODE ,SHUP.COMPANY_CODE ,SHUP.MANAGE_NUMBER ,SHUP.DOC_NO ,SHUP.STATUS ,SHUP.ADD_DATE ,SHUP.ADD_TIME ,SHUP.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHUP.HOUSE_CODE AND USMT.USER_ID = SHUP.ADD_USER_ID) AS ADD_USER_NAME_LOC ,SHUP.CHANGE_DATE ,SHUP.CHANGE_TIME ,SHUP.CHANGE_USER_ID ,(SELECT USER_NAME_LOC FROM SUSMT USMT WHERE USMT.HOUSE_CODE = SHUP.HOUSE_CODE AND USMT.USER_ID = SHUP.CHANGE_USER_ID) AS CHANGE_USER_NAME_LOC ,SHUP.DEL_FLAG ,SHUP.SUBJECT ,SHUP.CHANGE_SEAL_MG_DEPT ,SHUP.CHANGE_SEAL_MG_USER_ID ,SHUP.CHANGE_SUB_MG_DEPT ,SHUP.CHANGE_SUB_MG_USER_ID ,SHUP.CHANGE_REQUEST_DATE ,SHUP.CHANGE_ELECTRON_FLAG ,SHUP.CHANGE_REAL_FLAG ,SHUP.CHANGE_EXTERNAL_FLAG ,SHUP.CHANGE_SEAL_USE ,SHUP.CHANGE_REMARK1 ,SHUP.CHANGE_REMARK2 ,SHUP.CHANGE_REMARK3 ,SHUP.ELECTRON_FLAG ,SHUP.REAL_FLAG ,SHUP.EXTERNAL_FLAG ,SHUP.REASON ,SHUP.SEAL_TYPE ,SHUP.SEAL_MG_DEPT ,SHUP.SEAL_MG_USER_ID ,SHUP.SUB_MG_DEPT ,SHUP.SUB_MG_USER_ID ,SHUP.SEAL_USE ,SHUP.CAL_BASIS_131 ,SHUP.CAL_BASIS_132 ,SHUP.SEAL_ATTACH_NO ,SHUP.SEAL_USE_DEPT ,SHUP.SEAL_CATEGORY ,SHUP.PUBLIC_YN ,SHUP.CHANGE_SEAL_CATEGORY ,SHUP.CHANGE_PUBLIC_YN ,'UP' AS APPLY_TYPE ,#DB_OWNER#GETDEPTNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.CHANGE_SEAL_MG_DEPT, ${session.LANGUAGE}) AS CHANGE_SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.CHANGE_SEAL_MG_USER_ID, ${session.LANGUAGE}) AS CHANGE_SEAL_MG_USER_NAME ,#DB_OWNER#GETDEPTNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME ,#DB_OWNER#GETDEPTNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.CHANGE_SUB_MG_DEPT, ${session.LANGUAGE}) AS CHANGE_SUB_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.CHANGE_SUB_MG_USER_ID, ${session.LANGUAGE}) AS CHANGE_SUB_MG_USER_NAME ,#DB_OWNER#GETDEPTNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.SUB_MG_DEPT, ${session.LANGUAGE}) AS SUB_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SHUP.HOUSE_CODE, SHUP.COMPANY_CODE, SHUP.SUB_MG_USER_ID, ${session.LANGUAGE}) AS SUB_MG_USER_NAME ,SHUP.SEAL_DATE FROM SDCAM DCAM INNER JOIN SSHUP SHUP ON DCAM.HOUSE_CODE = SHUP.HOUSE_CODE AND DCAM.COMPANY_CODE = SHUP.COMPANY_CODE AND DCAM.CODE = SHUP.MANAGE_NUMBER AND DCAM.SEQ = SHUP.DOC_NO LEFT OUTER JOIN SUSMT USMT ON USMT.HOUSE_CODE = SHUP.HOUSE_CODE AND USMT.USER_ID = SHUP.SEAL_MG_USER_ID WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE}
AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND (
DCAM.USER_ID = ${session.ID} OR DCAM.USER_GROUP_CODE = ${session.DEPARTMENT}
)
AND DCAM.USER_COMPANY_CODE = $S{COMPANY_CODE} AND DCAM.USER_COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND SHUP.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND SHUP.DOC_NO = $S{DOC_NO} AND SHUP.STATUS IN( $INS{STATUS}) AND SHUP.STATUS = $S{F_STATUS} AND SHUP.ADD_DATE >= $S{F_CALENDAR_FROM} AND SHUP.ADD_DATE <= $S{F_CALENDAR_TO} AND #DB_OWNER#NVL(SHUP.DEL_FLAG, 'N') = 'N' AND ( 1=1 AND UPPER(SHUP.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHUP.DOC_NO) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SHUP.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND 'UP' IN ($INS{F_APPLY_TYPE})


DELETE
  FROM SSHNE
 WHERE 
	 	HOUSE_CODE 		= ${session.HOUSE_CODE}  
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}
	AND MANAGE_NUMBER	= ${MANAGE_NUMBER}
	AND DOC_NO			= ${DOC_NO}


 INSERT
   INTO SSHNE (
		 HOUSE_CODE
		,COMPANY_CODE
		,MANAGE_NUMBER
		,DOC_NO
		,STATUS
		,ADD_DATE
		,ADD_TIME
		,ADD_USER_ID
		,CHANGE_DATE
		,CHANGE_TIME
		,CHANGE_USER_ID
		,DEL_FLAG
		,SUBJECT
		,SEAL_TYPE
		,SEAL_MG_DEPT
		,SEAL_MG_USER_ID
		,SUB_MG_DEPT
		,SUB_MG_USER_ID
		,SEAL_USE
		,CAL_BASIS_131
		,CAL_BASIS_132
		,RECV_TYPE
		,SEAL_DATE
		,SEAL_ATTACH_NO
		,CONFIRM_DATE
		,SEND_DATE
		,SEND_USER_ID
		,RECV_USER_ID
		,RECV_DATE
		,RECV_ADDR
		,SEAL_USE_DEPT
		,ELECTRON_FLAG
		,REAL_FLAG
		,EXTERNAL_FLAG
		,REASON
		,CAL_REMARK	
		,SEAL_CATEGORY
		,PUBLIC_YN 
   	  )
  VALUES (
		 ${session.HOUSE_CODE}
		,${session.COMPANY_CODE}
		,${MANAGE_NUMBER}
		,${DOC_NO}
		,${STATUS}
		,${current.DATE}
		,${current.TIME}
		,${session.ID}
		,${current.DATE}
		,${current.TIME}
		,${session.ID}
		,'N'
		,${SUBJECT}
		,${SEAL_TYPE}
		,${SEAL_MG_DEPT}
		,${SEAL_MG_USER_ID}
		,${SUB_MG_DEPT}
		,${SUB_MG_USER_ID}
		,${SEAL_USE}
		,${CAL_BASIS_131}
		,${CAL_BASIS_132}
		,${RECV_TYPE}
		,${SEAL_DATE}
		,${SEAL_ATTACH_NO}
		,${CONFIRM_DATE}
		,${SEND_DATE}
		,${SEND_USER_ID}
		,${RECV_USER_ID}
		,${RECV_DATE}
		,${RECV_ADDR}
		,${SEAL_USE_DEPT}
		,${ELECTRON_FLAG}
		,${REAL_FLAG}
		,${EXTERNAL_FLAG}
		,${REASON}
		,${CAL_REMARK}
		,${SEAL_CATEGORY}
		,${PUBLIC_YN}
  	  )


