		,ADD_TIME
		,ADD_USER_ID
		,CHANGE_DATE
		,CHANGE_TIME
		,CHANGE_USER_ID
		,DEL_FLAG
		,SUBJECT
		,CHANGE_SEAL_MG_DEPT
		,CHANGE_SEAL_MG_USER_ID
		,CHANGE_SUB_MG_DEPT
		,CHANGE_SUB_MG_USER_ID
		,CHANGE_REQUEST_DATE
		,CHANGE_ELECTRON_FLAG
		,CHANGE_REAL_FLAG
		,CHANGE_EXTERNAL_FLAG
		,CHANGE_SEAL_USE
		,CHANGE_REMARK1
		,CHANGE_REMARK2
		,CHANGE_REMARK3
		,ELECTRON_FLAG
		,REAL_FLAG
		,EXTERNAL_FLAG
