  	  )


DELETE
  FROM SSHUP
 WHERE 
	 	HOUSE_CODE 		= ${session.HOUSE_CODE}  
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}
	AND MANAGE_NUMBER	= ${MANAGE_NUMBER}
	AND DOC_NO			= ${DOC_NO}

SELECT SEAL.HOUSE_CODE ,SEAL.COMPANY_CODE ,SEAL.MANAGE_NUMBER ,SEAL.ADD_DATE ,SEAL.ADD_TIME ,SEAL.ADD_USER_ID ,SEAL.CHANGE_DATE ,SEAL.CHANGE_TIME ,SEAL.CHANGE_USER_ID ,SEAL.DEL_FLAG ,SEAL.SUBJECT ,SEAL.SEAL_STATUS ,SEAL.SEAL_TYPE ,SEAL.SEAL_MG_DEPT ,SEAL.SEAL_MG_USER_ID ,SEAL.SUB_MG_DEPT ,SEAL.SUB_MG_USER_ID ,SEAL.CAL_BASIS_131 ,SEAL.CAL_BASIS_132 ,SEAL.RECV_TYPE ,SEAL.RECV_DATE ,SEAL.RECV_USER_ID ,SEAL.RECV_ADDR ,SEAL.SEAL_DATE ,SEAL.SEAL_ATTACH_NO ,SEAL.SEAL_USE_DEPT ,SEAL.CONFIRM_DATE ,SEAL.SEND_DATE ,SEAL.SEND_USER_ID ,CASE WHEN SEAL.ELECTRON_FLAG = 'Y' THEN '1' ELSE '0' END AS ELECTRON_FLAG ,CASE WHEN SEAL.REAL_FLAG = 'Y' THEN '1' ELSE '0' END AS REAL_FLAG ,CASE WHEN SEAL.EXTERNAL_FLAG = 'Y' THEN '1' ELSE '0' END AS EXTERNAL_FLAG ,#DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME ,#DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SUB_MG_DEPT, ${session.LANGUAGE}) AS SUB_MG_DEPT_NAME ,#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SUB_MG_USER_ID, ${session.LANGUAGE}) AS SUB_MG_USER_NAME ,SEAL.CAL_REMARK ,SEAL.SEAL_ID ,SEAL.SEAL_CATEGORY ,SEAL.PUBLIC_YN FROM SSEAL SEAL LEFT OUTER JOIN SUSMT USMT ON USMT.HOUSE_CODE = SEAL.HOUSE_CODE AND USMT.USER_ID = SEAL.SEAL_MG_USER_ID WHERE SEAL.HOUSE_CODE = ${session.HOUSE_CODE} AND SEAL.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND #DB_OWNER#NVL(SEAL.DEL_FLAG, 'N') = 'N' AND ( 1=1 AND UPPER(SEAL.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SEAL.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND SEAL.SEAL_STATUS = $S{SEAL_STATUS} AND SEAL.SEAL_MG_USER_ID = $S{SEAL_MG_USER_ID} AND SEAL.SEAL_MG_DEPT = $S{USER_DEPT} AND SEAL.SEAL_DATE >= $S{F_CALENDAR_FROM} AND SEAL.SEAL_DATE <= $S{F_CALENDAR_TO} AND SEAL.SEAL_TYPE IN($INS{SEAL_TYPE})
AND SEAL.COMPANY_CODE = ${session.COMPANY_CODE}
AND SEAL.COMPANY_CODE = ${session.COMPANY_CODE}
AND SEAL.COMPANY_CODE = $S{COMPANY_CODE} AND SEAL.COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
ORDER BY SEAL.COMPANY_CODE, SEAL.MANAGE_NUMBER DESC


