/* SepoaSealManagementManager.doSelectSUDGL */ SELECT HOUSE_CODE ,COMPANY_CODE ,USE_NUMBER ,ADD_DATE ,ADD_TIME ,ADD_USER_ID ,CHANGE_DATE ,CHANGE_TIME ,CHANGE_USER_ID ,DEL_FLAG ,SUBJECT ,CONTENT ,SORT_SEQ ,CORP_FLAG ,USE_FLAG ,EXTERNAL_FLAG ,FORM_ID FROM SUDGL WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND USE_NUMBER = $S{USE_NUMBER}
AND COMPANY_CODE = ${session.COMPANY_CODE}
AND COMPANY_CODE = ${session.COMPANY_CODE}
AND COMPANY_CODE = $S{COMPANY_CODE} AND COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})

/* SepoaSealManagementManager.doSelectSealUseInfo */ SELECT SUSE.HOUSE_CODE ,SUSE.COMPANY_CODE ,SUSE.ADD_DATE ,SUSE.ADD_TIME ,SUSE.ADD_USER_ID ,SUSE.CHANGE_DATE ,SUSE.CHANGE_TIME ,SUSE.CHANGE_USER_ID ,SUSE.DEL_FLAG ,SUSE.MANAGE_NUMBER ,SUSE.USE_NUMBER ,UDGL.SUBJECT FROM SSUSE SUSE INNER JOIN SUDGL UDGL ON SUSE.HOUSE_CODE = UDGL.HOUSE_CODE AND SUSE.COMPANY_CODE = UDGL.COMPANY_CODE AND SUSE.USE_NUMBER = UDGL.USE_NUMBER WHERE SUSE.HOUSE_CODE = ${session.HOUSE_CODE} AND SUSE.MANAGE_NUMBER = ${MANAGE_NUMBER}
AND SUSE.COMPANY_CODE = ${session.COMPANY_CODE}
AND SUSE.COMPANY_CODE = ${session.COMPANY_CODE}
AND SUSE.COMPANY_CODE = $S{COMPANY_CODE}

/* SepoaSealManagementManager.doSelectSealMappedUse */ SELECT * FROM( SELECT ROW_NUMBER() OVER (PARTITION BY SEAL.MANAGE_NUMBER ORDER BY A.CHANGE_DATE DESC, A.CHANGE_TIME DESC) AS RNUM , SEAL.HOUSE_CODE , SEAL.COMPANY_CODE , SEAL.MANAGE_NUMBER , SEAL.SUBJECT , SEAL.SEAL_STATUS , SEAL.SEAL_TYPE , SEAL.SEAL_CATEGORY , CODE.TEXT1 AS CATEGORY_NAME , SEAL.SEAL_MG_DEPT , SEAL.SEAL_MG_USER_ID , SEAL.ELECTRON_FLAG , SEAL.REAL_FLAG , UPIM.ITEM_NAME , UPIM.ITEM_CODE , UPIM.ITEM_TYPE , UPIM.SEAL_WIDTH , UPIM.SEAL_HEIGHT , UPIM.ITEM_NO , #DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS SEAL_MG_USER_NAME , #DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_DEPT, ${session.LANGUAGE}) AS SEAL_MG_DEPT_LOC , CASE WHEN A.COMPLETE_FLAG IS NULL THEN 'Y' ELSE A.COMPLETE_FLAG END AS COMPLETE_FLAG , CASE WHEN A.CHANGE_DATE IS NULL THEN '' ELSE A.CHANGE_DATE END AS CHANGE_DATE , CASE WHEN A.CHANGE_TIME IS NULL THEN '' ELSE A.CHANGE_TIME END AS CHANGE_TIME , SETL.EXT_OUT_EXPECT_DATE , SETL.EXT_OUT_EXPECT_TIME , SETL.EXT_IN_EXPECT_DATE , SETL.EXT_IN_EXPECT_TIME FROM SSEAL SEAL INNER JOIN SSUSE SUSE ON SUSE.HOUSE_CODE = SEAL.HOUSE_CODE AND SUSE.COMPANY_CODE = SEAL.COMPANY_CODE AND SUSE.MANAGE_NUMBER = SEAL.MANAGE_NUMBER AND SUSE.USE_NUMBER IN($INS{SEAL_USE_TYPE}) INNER JOIN SUPIM UPIM ON UPIM.HOUSE_CODE = SEAL.HOUSE_CODE AND UPIM.COMPANY_CODE = SEAL.COMPANY_CODE AND UPIM.ITEM_CODE = SEAL.SEAL_TYPE LEFT OUTER JOIN SCODE CODE ON CODE.HOUSE_CODE = SEAL.HOUSE_CODE AND CODE.TYPE = 'SC001' AND CODE.CODE = SEAL.SEAL_CATEGORY AND CODE.LANGUAGE = ${session.LANGUAGE} LEFT OUTER JOIN SSEDC_SEAL A ON A.HOUSE_CODE = SEAL.HOUSE_CODE AND A.COMPANY_CODE = SEAL.COMPANY_CODE AND A.MANAGE_NUMBER = SEAL.MANAGE_NUMBER LEFT OUTER JOIN SSETL SETL ON SETL.HOUSE_CODE = A.HOUSE_CODE AND SETL.COMPANY_CODE = A.COMPANY_CODE AND SETL.SMR_NUMBER = A.SMR_NUMBER WHERE SEAL.HOUSE_CODE = ${session.HOUSE_CODE} AND SEAL.COMPANY_CODE = ${session.COMPANY_CODE} AND SEAL.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND SEAL.SEAL_TYPE IN($INS{SEAL_TYPE}) AND (UPPER(SEAL.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(SEAL.SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(#DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, '#session.LANGUAGE#')) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(#DB_OWNER#GETUSERDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, '#session.LANGUAGE#')) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') ) AND SEAL.SEAL_STATUS IN($INS{SEAL_STATUS}) AND SEAL.EXTERNAL_FLAG = $S{EXTERNAL_FLAG} AND SEAL.ELECTRON_FLAG = $S{ELECTRON_FLAG} AND SEAL.REAL_FLAG = $S{REAL_FLAG} AND SEAL.SEAL_MG_DEPT = $S{SEAL_MG_DEPT}
AND (${session.DEPARTMENT} = SEAL.SEAL_MG_DEPT OR SEAL.PUBLIC_YN ='Y')
) B WHERE B.RNUM = 1;


/* SepoaSealManagementManager.doSelectSUSMT */
	SELECT
