INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${session.COMPANY_CODE}     
      ,${SMR_NUMBER}        
      ,'1'      
      ,(SELECT COUNT(*) + 1
          FROM SPMGT InPMGT
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${SMR_NUMBER}
           AND InPMGT.CONT_GL_SEQ  = '1'
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${session.ID}
      ,${ACTION}           
      ,${IP}
     )


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND CONT_NO      = ${SMR_NUMBER}
   AND CONT_GL_SEQ  = '1'

/* SepoaSealManagementManager.doSealHistoryList */ SELECT TMHI.HOUSE_CODE ,TMHI.COMPANY_CODE ,TMHI.SEAL_ID ,TMHI.PUBLISH_NO ,TMHI.SEAL_TYPE ,TMHI.SMR_NUMBER ,TMHI.SMD_NUMBER ,TMHI.DOC_SUBJECT ,TMHI.MANAGE_NUMBER ,TMHI.ADD_DATE ,TMHI.ADD_TIME ,TMHI.ADD_USER_ID ,CASE ${session.LANGUAGE} WHEN 'KO' THEN USMT.USER_NAME_LOC ELSE USMT.USER_NAME_ENG END AS ADD_USER_NAME ,SIAD.SUBJECT AS SMR_SUBJECT ,#DB_OWNER#GETUSERDEPTNAME('#session.HOUSE_CODE#', '#session.COMPANY_CODE#', TMHI.ADD_USER_ID, '#session.LANGUAGE#') AS DEPT ,#DB_OWNER#GETCODETEXT1('#session.HOUSE_CODE#', 'UX049', USMT.POSITION, '#session.LANGUAGE#') AS POSITION FROM STMHI TMHI LEFT OUTER JOIN SUSMT USMT ON TMHI.HOUSE_CODE = USMT.HOUSE_CODE AND TMHI.ADD_USER_ID = USMT.USER_ID INNER JOIN SSIAD SIAD ON TMHI.HOUSE_CODE = SIAD.HOUSE_CODE AND TMHI.COMPANY_CODE = SIAD.COMPANY_CODE AND TMHI.SMR_NUMBER = SIAD.SMR_NUMBER WHERE TMHI.HOUSE_CODE = ${session.HOUSE_CODE} AND TMHI.ADD_DATE >= $S{F_CALENDAR_FROM} AND TMHI.ADD_DATE <= $S{F_CALENDAR_TO} AND TMHI.SEAL_TYPE IN (#SEAL_TYPE#) AND ( 1=1 AND UPPER(TMHI.SEAL_ID) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.PUBLISH_NO) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.SEAL_TYPE) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.SMR_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.SMD_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.DOC_SUBJECT) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.MANAGE_NUMBER) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(TMHI.ADD_USER_ID) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') OR UPPER(USMT.USER_NAME_LOC) LIKE CONCAT('%', UPPER($S{F_KEYWORD}), '%') )
AND TMHI.COMPANY_CODE = ${session.COMPANY_CODE}
AND TMHI.COMPANY_CODE = ${session.COMPANY_CODE}
AND TMHI.COMPANY_CODE = $S{COMPANY_CODE} AND TMHI.COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
ORDER BY TMHI.ADD_DATE DESC, TMHI.ADD_TIME DESC, TMHI.SMR_NUMBER, TMHI.SMD_NUMBER, TMHI.MANAGE_NUMBER


    	INSERT
