SELECT APUD.HOUSE_CODE ,APUD.COMPANY_CODE ,APUD.APP_USER_ID ,APUD.APP_USER_DEPT ,APUD.APP_SORT ,APUD.CHANGE_FLAG ,APUD.DEL_FLAG ,USMT.USER_NAME_LOC ,DEPT.DEPT_NAME_LOC FROM SAPUD APUD INNER JOIN SUSMT USMT ON USMT.HOUSE_CODE = APUD.HOUSE_CODE AND USMT.USER_ID = APUD.APP_USER_ID INNER JOIN SDEPT DEPT ON DEPT.HOUSE_CODE = USMT.HOUSE_CODE AND DEPT.COMPANY_CODE = APUD.COMPANY_CODE AND DEPT.DEPT = APUD.APP_USER_DEPT WHERE APUD.HOUSE_CODE = ${session.HOUSE_CODE} AND APUD.KEY_NUMBER = ${KEY_NUMBER} AND APUD.APP_USER_ID = $S{APP_USER_ID} AND APUD.CHANGE_FLAG IN ($INS{CHANGE_FLAG}) AND APUD.DEL_FLAG IN ($INS{DEL_FLAG})
AND APUD.COMPANY_CODE = ${session.COMPANY_CODE}
AND APUD.COMPANY_CODE = ${session.COMPANY_CODE}
AND APUD.COMPANY_CODE = ${COMPANY_CODE}


